(4, 'Dilshan Madusanka', 3, 'Best prices for genuine Korean flagship phones in Sri Lanka. Got my device delivered with official checking warranty. Smooth transaction and very friendly staff!"', 'Approved', 3, '2026-11-02 05:24:28', '2026-11-02 05:23:52', '2026-11-02 05:24:28'),
(5, 'Nimali Fernando', 5, 'I traded in my old iPhone 12 for an iPhone 14 Pro. They gave me the best valuation in the market without any hassle, and the top-up payment was so transparent. Highly recommended for phone upgrades!', 'Approved', 3, '2026-11-02 05:24:28', '2026-11-02 05:24:18', '2026-11-02 05:24:28'),
(6, 'pasindu', 4, 'test', 'Approved', 3, '2026-11-03 18:21:12', '2026-11-03 18:19:42', '2026-11-03 18:21:12'),
